          q: { type: "choice", values: [5, 7, 11, 13] },
          // k=1 → несократимая (num=p, den=q), k>1 → сократимая
          k: { type: "choice", values: [1, 1, 2, 3] },
          // 1 встречается чаще
          num: { type: "expression", value: "p * k" },
          den: { type: "expression", value: "q * k" }
